#include <stdio.h>

int main(void) {
    const long long VAT_PERCENT = 20;
    long long price, count;
    scanf("%lld %lld", &price, &count);
    long long total = price * count * (100 + VAT_PERCENT) / 100;
    printf("%lld.%02lld\n", total / 100, total % 100);
    return 0;
}

